const base = { motorista_id: r.motorista_id, passageiro_id: r.passageiro_id, passageiro_nome: r.passageiro_nome };
const out = [];
for (const d of dividas) {
  if (restante <= 0) break;
  const devido = Number(d.valor_devido || 0);
