  if (pagar <= 0) continue;
  restante = r2(restante - pagar);
  const novoPago = r2(jaPago + pagar);
  out.push({ json: { ...base, valor: pagar, referencia: d.referencia || refAtual,
    divida_id: d.id, novo_pago: novoPago, quitada: novoPago >= devido - 0.005, abatido: pagar } });
}
if (restante > 0.004) {
  out.push({ json: { ...base, valor: restante, referencia: refAtual, divida_id: null } });
}
return out;

