  const manut = /oleo|pneu|freio|revisao|mecanico|oficina|manutencao|bateria|suspensao|alinhamento|balanceamento|filtro/.test(texto);
  const descricao = L.descricao || L.estabelecimento || 'nota fiscal';
  const tipo = manut ? 'manutencao' : 'despesa';
  const linhas = [`🧾 *Li uma nota${L.estabelecimento ? ' de ' + L.estabelecimento : ''}:*`, `💰 Total: ${brl(L.valor)}`];
  if (L.descricao) linhas.push(`📝 ${L.descricao}`);
  if (L.data) linhas.push(`📅 ${fmt(L.data)}`);
  linhas.push('', `Registro como ${manut ? 'manutenção 🔧' : 'despesa 💸'}? Responde *sim* ou *não* (vale por 30 min).`);
  return responder(linhas.join('\n'), { tipo, payload: { intencao: tipo, valor: L.valor, descricao } });
}

// pix: tenta casar o nome do pagador (depois o do recebedor) com os passageiros cadastrados
const tokens = s => sem(s).replace(/[^a-z0-9 ]/g, ' ').split(' ').filter(t => t.length > 0);
const achar = nomePix => {
  const q = tokens(nomePix);
  if (!q.length) return [];
  const casados = passageiros.filter(p => {
    const pt = tokens(p.nome).filter(t => t.length >= 2);
    return pt.length > 0 && pt.every(t => q.some(w => w.startsWith(t)));
  });
  if (!casados.length) return [];
  const max = Math.max(...casados.map(p => tokens(p.nome).length));
  return casados.filter(p => tokens(p.nome).length === max);
};
const candidatos = achar(L.pagador);

if (!candidatos.length) {
  return responder(`💰 Li um Pix de *${brl(L.valor)}*${L.pagador ? ' de ' + L.pagador : ''}, mas não achei um passageiro com esse nome.\nMe diga quem pagou, tipo: "recebi ${numTxt(L.valor)} do João" 😊`);
}
if (candidatos.length > 1) {
  return responder(`💰 Li um Pix de ${brl(L.valor)}${L.pagador ? ' de ' + L.pagador : ''}, mas mais de um passageiro combina:\n${candidatos.map(p => '• ' + p.nome).join('\n')}\n\nMe diga quem foi, tipo: "recebi ${numTxt(L.valor)} do João" 😊`);
}
const p = candidatos[0];
const linhas = [`💰 *Li um Pix de ${brl(L.valor)}*`];
if (L.data) linhas.push(`📅 ${fmt(L.data)}`);
if (L.pagador) linhas.push(`👤 De: ${L.pagador}`);
if (L.recebedor) linhas.push(`➡️ Para: ${L.recebedor}`);
linhas.push('', `Registro como pagamento de *${p.nome}*? Responde *sim* ou *não* (vale por 30 min).`);
return responder(linhas.join('\n'), { tipo: 'pagamento', payload: { intencao: 'pagamento', valor: L.valor, descricao: p.nome } });

const ctx = $('Interpretar').first().json;
const h = $input.all().map(i => i.json).find(x => x.id);
if (!h) {
  return [{ json: { phone: ctx.phone, pend: null, message: '🤔 Não encontrei nenhum registro para desfazer.' } }];
}
const dt = DateTime.fromISO(String(h.created_at)).setZone('America/Sao_Paulo');
const quando = dt.isValid ? dt.toFormat("dd/MM 'às' HH:mm") : '';
const message = `↩️ Vou desfazer o último registro:\n\n${h.resumo}${quando ? `\n🕒 ${quando}` : ''}\n\nConfirma? Responde *sim* ou *não* (vale por 30 min).`;
return [{ json: { phone: ctx.phone, message,
  pend: { tipo: 'desfazer', payload: { intencao: 'desfazer_confirmado', historico_id: h.id } } } }];

const ctx = $('Interpretar').first().json;
const h = $input.all().map(i => i.json).find(x => x.id);

// sem nada para desfazer: devolve uma operação vazia (GET sem linhas) só para o fluxo seguir e responder
const vazio = message => [{ json: { vazio: true, phone: ctx.phone, message,
  metodo: 'GET', tabela: 'historico_acoes', filtro: 'select=id&limit=0' } }];

if (!h) return vazio('🤔 Esse registro já foi desfeito ou não existe mais. Me manda "desfazer" de novo para ver o anterior.');

const p = h.payload || {};
const seguro = x => /^[A-Za-z0-9_-]+$/.test(String(x));
const ids = (Array.isArray(p.ids) ? p.ids : []).filter(seguro).map(String);
const lista = ids.join(',');
const dono = `motorista_id=eq.${ctx.motorista_id}`;          // nunca mexe em registro de outro motorista
const TAB = { despesa: 'despesas', manutencao: 'manutencoes', documento: 'documentos', pagamento: 'pagamentos', passageiro: 'passageiros' };
const tabela = TAB[h.tipo];

if (!tabela || !lista) return vazio(`⚠️ Não consegui desfazer isso automaticamente: ${h.resumo}`);

const ops = [];
if (h.tipo === 'passageiro') {
  // cadastro de passageiro: só desativa (não apaga), para não quebrar histórico de pagamentos
  ops.push({ metodo: 'PATCH', tabela, filtro: `id=in.(${lista})&${dono}`, body: { ativo: false } });
} else {
  ops.push({ metodo: 'DELETE', tabela, filtro: `id=in.(${lista})&${dono}` });
}
if (h.tipo === 'pagamento') {
  // reabre as dívidas que esse pagamento abateu, devolvendo o valor pago que elas tinham antes
  for (const d of (Array.isArray(p.dividas) ? p.dividas : [])) {
    if (!seguro(d.id)) continue;
    ops.push({ metodo: 'PATCH', tabela: 'inadimplencias', filtro: `id=eq.${d.id}&${dono}`,
      body: { valor_pago: Number(d.valor_pago_antes) || 0, resolvido: false, resolvido_em: null } });
  }
}
// por último, marca o histórico como desfeito
ops.push({ metodo: 'PATCH', tabela: 'historico_acoes', filtro: `id=eq.${h.id}&${dono}`,
  body: { desfeita: true, desfeita_em: $now.toUTC().toISO() } });

return ops.map(o => ({ json: { vazio: false, phone: ctx.phone, resumo: h.resumo, ...o } }));

const m = $('Montar Desfazer').first().json;
const falhas = $('Executar Operação').all().filter(i => i.json && i.json.error).length;
let message;
if (m.vazio) message = m.message;
else if (falhas) message = `⚠️ Desfiz só em parte: ${m.resumo}\nConfira em "resumo" e me avise se algo ficou errado.`;
else message = `↩️ Desfeito: ${m.resumo}\n\nSe quiser, me manda o registro certo 😉`;
return [{ json: { phone: m.phone, message } }];
